-- Canonical Brain Heist English skill registry with Cambridge programme crosswalks.
-- Canonical skill identity is owned by Brain Heist; Cambridge references remain external alignment metadata.

create table if not exists public.academic_skill_registry_versions (
  id uuid primary key default gen_random_uuid(),
  code text not null unique,
  subject_key text not null,
  title text not null,
  description text not null,
  authority_model text not null,
  status text not null check (status in ('draft','published','retired')),
  effective_from date,
  created_at timestamptz not null default now()
);
create table if not exists public.academic_skill_registry_nodes (
  id uuid primary key default gen_random_uuid(),
  registry_version_id uuid not null references public.academic_skill_registry_versions(id) on delete restrict,
  parent_id uuid references public.academic_skill_registry_nodes(id) on delete restrict,
  node_type text not null check (node_type in ('strand','skill','subskill')),
  code text not null unique,
  name text not null,
  description text not null,
  applicable_phases text[] not null default '{}',
  status text not null default 'active' check (status in ('active','retired')),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  check (array_length(applicable_phases,1) is not null),
  check (applicable_phases <@ array['primary','lower_secondary','upper_secondary','advanced']::text[])
);
create table if not exists public.academic_skill_registry_aliases (
  id uuid primary key default gen_random_uuid(),
  registry_version_id uuid not null references public.academic_skill_registry_versions(id) on delete restrict,
  node_id uuid not null references public.academic_skill_registry_nodes(id) on delete restrict,
  alias text not null,
  alias_normalized text not null,
  alias_type text not null default 'legacy' check (alias_type in ('legacy','teacher','ai_proposal','synonym')),
  created_at timestamptz not null default now(),
  unique (registry_version_id, alias_normalized)
);
create table if not exists public.academic_skill_framework_crosswalks (
  id uuid primary key default gen_random_uuid(),
  registry_version_id uuid not null references public.academic_skill_registry_versions(id) on delete restrict,
  node_id uuid not null references public.academic_skill_registry_nodes(id) on delete restrict,
  provider_name text not null,
  programme_code text not null,
  programme_name text not null,
  phase text not null check (phase in ('primary','lower_secondary','upper_secondary','advanced')),
  external_strand text,
  external_reference_code text,
  alignment_level text not null check (alignment_level in ('programme','strand','assessment_objective','subject_content')),
  alignment_note text not null,
  source_url text not null,
  source_version text,
  status text not null default 'active' check (status in ('active','retired')),
  created_at timestamptz not null default now()
);
create index if not exists academic_skill_registry_nodes_version_type_idx on public.academic_skill_registry_nodes(registry_version_id,node_type,status);
create index if not exists academic_skill_registry_nodes_parent_idx on public.academic_skill_registry_nodes(parent_id,status);
create index if not exists academic_skill_registry_aliases_norm_idx on public.academic_skill_registry_aliases(alias_normalized);
create index if not exists academic_skill_framework_crosswalks_programme_idx on public.academic_skill_framework_crosswalks(programme_code,phase,status);
create unique index if not exists academic_skill_framework_crosswalks_unique_idx
  on public.academic_skill_framework_crosswalks(node_id,programme_code,coalesce(external_reference_code,''),alignment_level);

alter table public.academic_skill_registry_versions enable row level security;
alter table public.academic_skill_registry_nodes enable row level security;
alter table public.academic_skill_registry_aliases enable row level security;
alter table public.academic_skill_framework_crosswalks enable row level security;
revoke all on public.academic_skill_registry_versions from public,anon,authenticated,service_role;
revoke all on public.academic_skill_registry_nodes from public,anon,authenticated,service_role;
revoke all on public.academic_skill_registry_aliases from public,anon,authenticated,service_role;
revoke all on public.academic_skill_framework_crosswalks from public,anon,authenticated,service_role;
grant select on public.academic_skill_registry_versions,public.academic_skill_registry_nodes,
  public.academic_skill_registry_aliases,public.academic_skill_framework_crosswalks to authenticated,service_role;

drop policy if exists "Authenticated can read published skill registry versions" on public.academic_skill_registry_versions;
create policy "Authenticated can read published skill registry versions" on public.academic_skill_registry_versions
  for select to authenticated using (status='published');
drop policy if exists "Authenticated can read active skill registry nodes" on public.academic_skill_registry_nodes;
create policy "Authenticated can read active skill registry nodes" on public.academic_skill_registry_nodes
  for select to authenticated using (status='active' and exists (
    select 1 from public.academic_skill_registry_versions v where v.id=registry_version_id and v.status='published'
  ));
drop policy if exists "Authenticated can read skill registry aliases" on public.academic_skill_registry_aliases;
create policy "Authenticated can read skill registry aliases" on public.academic_skill_registry_aliases
  for select to authenticated using (exists (
    select 1 from public.academic_skill_registry_versions v where v.id=registry_version_id and v.status='published'
  ));
drop policy if exists "Authenticated can read skill framework crosswalks" on public.academic_skill_framework_crosswalks;
create policy "Authenticated can read skill framework crosswalks" on public.academic_skill_framework_crosswalks
  for select to authenticated using (status='active' and exists (
    select 1 from public.academic_skill_registry_versions v where v.id=registry_version_id and v.status='published'
  ));

insert into public.academic_skill_registry_versions(code,subject_key,title,description,authority_model,status,effective_from)
values ('bh-english-core-v1','english','Brain Heist English Core Skill Registry v1',
