insert into public.academic_skill_registry_nodes(registry_version_id,parent_id,node_type,code,name,description,applicable_phases,status)
select v.id,p.id,'skill',s.code,s.name,s.description,s.phases,'active'
from v cross join seed s join public.academic_skill_registry_nodes p on p.code=s.parent_code
on conflict (code) do update set parent_id=excluded.parent_id,name=excluded.name,description=excluded.description,applicable_phases=excluded.applicable_phases,status='active',updated_at=now();

