insert into public.academic_skill_registry_aliases(registry_version_id,node_id,alias,alias_normalized,alias_type)
select v.id,n.id,s.alias,s.alias_normalized,s.alias_type from v cross join seed s
join public.academic_skill_registry_nodes n on n.code=s.node_code
on conflict (registry_version_id,alias_normalized) do update set node_id=excluded.node_id,alias=excluded.alias,alias_type=excluded.alias_type;

