insert into public.academic_skill_framework_crosswalks(
  registry_version_id,node_id,provider_name,programme_code,programme_name,phase,external_strand,
  external_reference_code,alignment_level,alignment_note,source_url,source_version,status
)
select v.id,n.id,s.provider_name,s.programme_code,s.programme_name,s.phase,s.external_strand,
  s.external_reference_code,s.alignment_level,s.alignment_note,s.source_url,s.source_version,s.status
from v cross join seed s join public.academic_skill_registry_nodes n on n.code=s.node_code
on conflict do nothing;

CREATE OR REPLACE FUNCTION public.rpc_academic_skill_registry_for_generation(p_subject_key text, p_grade_level integer, p_phase text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare v_phase text;
begin
 if lower(trim(coalesce(p_subject_key,''))) not in ('english','esl','english as a second language') then
   return jsonb_build_object('success',true,'supported',false,'reason','registry_not_available_for_subject');
 end if;
 v_phase:=coalesce(nullif(trim(p_phase),''),
   case when p_grade_level between 1 and 6 then 'primary'
        when p_grade_level between 7 and 9 then 'lower_secondary'
        else 'upper_secondary' end);
 if v_phase not in ('primary','lower_secondary','upper_secondary') then
   raise exception using errcode='22023',message='invalid_registry_phase';
 end if;
 return jsonb_build_object(
  'success',true,'supported',true,'registryVersion','bh-english-core-v1','phase',v_phase,
  'cambridgeProgrammes',case v_phase
    when 'primary' then jsonb_build_array(jsonb_build_object('code','0057','name','Cambridge Primary English as a Second Language'))
    when 'lower_secondary' then jsonb_build_array(jsonb_build_object('code','0876','name','Cambridge Lower Secondary English as a Second Language'))
    else jsonb_build_array(
      jsonb_build_object('code','0472','name','Cambridge IGCSE English as an Additional Language'),
      jsonb_build_object('code','0510','name','Cambridge IGCSE English as a Second Language (Speaking Endorsement)'),
      jsonb_build_object('code','0511','name','Cambridge IGCSE English as a Second Language (Count-in Speaking)')) end,
  'rules',jsonb_build_array(
    'Select canonical codes from this registry; do not invent a new official skill or subskill.',
    'Skill identity describes the language competency, not the assessment process.',
    'Keep question-specific wording in the evidence statement, not the canonical skill name.',
    'Cambridge external AO references and Brain Heist cognitive-process codes are separate namespaces.',
    'If no canonical subskill fits, require taxonomy review instead of silently creating one.'),
  'skills',coalesce((
    select jsonb_agg(jsonb_build_object(
      'strandCode',strand.code,'strandName',strand.name,
      'skillCode',skill.code,'skillName',skill.name,'skillDescription',skill.description,
      'subskillCode',leaf.code,'subskillName',leaf.name,'subskillDescription',leaf.description
    ) order by strand.code,skill.code,leaf.code)
    from public.academic_skill_registry_versions v
    join public.academic_skill_registry_nodes leaf on leaf.registry_version_id=v.id and leaf.node_type='subskill' and leaf.status='active'
    join public.academic_skill_registry_nodes skill on skill.id=leaf.parent_id and skill.status='active'
    join public.academic_skill_registry_nodes strand on strand.id=skill.parent_id and strand.status='active'
    where v.code='bh-english-core-v1' and v.status='published' and v_phase=any(leaf.applicable_phases)
  ),'[]'::jsonb)
 );
end;$function$
;

revoke all on function public.rpc_academic_skill_registry_for_generation(text,integer,text)
from public,anon,authenticated,service_role;
grant execute on function public.rpc_academic_skill_registry_for_generation(text,integer,text)
to authenticated,service_role;

comment on table public.academic_skill_registry_nodes is
  'Canonical Brain Heist longitudinal skill identities. AI may select these identities but must not invent replacements during ordinary question generation.';
comment on table public.academic_skill_framework_crosswalks is
  'External framework crosswalks. Cambridge references are alignment metadata and never replace the stable Brain Heist skill identity.';
comment on function public.rpc_academic_skill_registry_for_generation(text,integer,text) is
  'Returns the published English canonical skill registry filtered by phase for governed question-generation taxonomy selection.';
